(()=>{'use strict';
const VERSION='20260728-player-tabs-shell-logos-v1',ROUTES=`player-data/routes.json?v=${VERSION}`,ALIASES=`player-data/aliases.json?v=${VERSION}`,CURRENT_STATS=`ffws-br-2026-s2/player-stats.json?v=${VERSION}`;const root=document.getElementById('player-root'),params=new URLSearchParams(location.search),cache=new Map(),state={route:null,player:null,current:null,seasonData:null,active:'s2'};const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])),norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'').toLowerCase(),num=v=>Number(v)||0,fmt=v=>num(v).toLocaleString('pt-BR'),avg=(a,b)=>b?(num(a)/num(b)).toFixed(2):'0.00';async function getJSON(url){if(cache.has(url))return cache.get(url);const p=fetch(url,{cache:'default'}).then(r=>{if(!r.ok)throw new Error(`Falha ao carregar ${url.split('?')[0]}`);return r.json()});cache.set(url,p);return p}function logo(name,current=''){return window.cffResolveTeamLogo?.(name,current)||current||'escudo.webp'}function logoImg(name,current,cls=''){return`<img class="${cls}" src="${esc(logo(name,current))}" data-team-logo="${esc(name)}" loading="lazy" decoding="async" alt="${esc(name)}">`}function stat(label,value,sub='',rank='',attr=''){return`<div class="stat-card"${attr?` ${attr}`:''}><small>${esc(label)}</small><strong>${esc(value)}</strong>${sub?`<span>${esc(sub)}</span>`:''}${rank?`<span class="rank-pill">#${esc(rank)}</span>`:''}</div>`}function titleStat(label,type){return stat(label,'—','Carregando registros','','data-title-'+type)}function stageRows(stages={}){const labels={groups:'Fase de Grupos',classificatoria:'Classificatória',survival:'Repescagem',repescagem:'Repescagem',final:'Final','fase2-dia1':'Fase 2 · Dia 1','fase2-dia2':'Fase 2 · Dia 2','fase2-dia3':'Fase 2 · Dia 3','fase2-dia4':'Fase 2 · Dia 4','last-chance':'Última Chance'};const rows=Object.entries(stages||{});return rows.length?`<div class="stage-list">${rows.map(([k,s])=>`<div class="stage-row"><strong>${esc(labels[k]||k)}</strong><span>${fmt(s.kills)} K</span><span>${fmt(s.matches)} Q</span><span>${s.matches?avg(s.kills,s.matches):'0.00'} K/Q</span><span>${s.damage!=null?`${fmt(s.damage)} dano`:'—'}</span></div>`).join('')}</div>`:''}function editionRow(e){return`<div class="edition-row"><div><strong>${esc(e.edition||e.name||'Edição')}</strong><small>${esc(e.team||e.status||'')}</small></div><div class="edition-stat"><b>${fmt(e.kills)}</b><span>Abates</span></div><div class="edition-stat"><b>${fmt(e.matches)}</b><span>Quedas</span></div><div class="edition-stat"><b>${Number(e.avg??(e.matches?num(e.kills)/num(e.matches):0)).toFixed(2)}</b><span>Média</span></div><div class="edition-stat"><b>${e.damage?fmt(e.damage):'—'}</b><span>Dano</span></div></div>`}function teamCard(e){return`<div class="team-history-card">${logoImg(e.team,e.logo,'team-history-logo')}<div><strong>${esc(e.team||'Equipe')}</strong><small>${esc(e.edition||e.cargo||'')}</small></div></div>`}function hero(p,type){const r=p.currentRoster||{},status=type==='full'?'JOGADOR DA WB 2026 S2':type==='historical'?'PERFIL HISTÓRICO':'PERFIL COMPETITIVO',team=p.currentTeam||p.lastTeam||'',teamLogo=p.currentTeamLogo||p.lastTeamLogo||'',badges=[r.captain?'<span class="profile-badge gold">Capitão</span>':'',r.rookie?'<span class="profile-badge">Estreante na WB 2026 S2</span>':'',r.starter?'<span class="profile-badge">Titular</span>':r.rosterStatus?`<span class="profile-badge">${esc(r.rosterStatus)}</span>`:''].join('');return`<section class="profile-hero profile-${type}"><div class="profile-photo-wrap"><img class="profile-photo" src="${esc(p.photo||'silhueta.webp')}" decoding="async" onerror="this.onerror=null;this.src='silhueta.webp'" alt="${esc(p.name)}">${team?logoImg(team,teamLogo,'profile-team-logo'):''}</div><div><div class="profile-kicker">${status}</div><h1 class="profile-name">${esc(p.name)}</h1>${team?`<a class="profile-team" href="equipe.html?time=${encodeURIComponent(team)}">${esc(team)}</a>`:''}<div class="profile-meta">${esc(p.role||r.role||'Jogador')}${r.fullName?` • ${esc(r.fullName)}`:''}${r.state?` • ${esc(r.state)}`:''}</div><div class="profile-badges">${badges}</div></div></section>`}function allTimeSection(p,includeTitles=true){const a=p.allTime||{};return`<section class="profile-section"><div class="profile-section-head"><h2>Desempenho histórico — All-Time</h2><p>Competições registradas no site</p></div><div class="stats-grid historical-grid${includeTitles?'':' compact-history'}">${stat('Kills históricas',fmt(a.kills))}${stat('Quedas jogadas',fmt(a.matches))}${stat('Média histórica',Number(a.avg??(a.matches?num(a.kills)/num(a.matches):0)).toFixed(2))}${includeTitles?titleStat('Títulos coletivos','collective')+titleStat('Títulos individuais','individual'):''}</div></section>`}function histories(p){const editions=(p.editions||[]).filter(e=>num(e.kills)||num(e.matches)||e.status),teams=p.teamHistory||[];return`${editions.length?`<section class="profile-section"><div class="profile-section-head"><h2>Histórico por edições</h2><p>Resultados cadastrados</p></div><div class="edition-list">${editions.slice().reverse().map(editionRow).join('')}</div></section>`:''}<section class="profile-section"><div class="profile-section-head"><h2>Passagens por equipes</h2><p>Da primeira à organização mais recente</p></div><div class="team-history-list" id="profile-team-history">${teams.map(teamCard).join('')||'<div class="season-empty">Histórico de equipes em atualização.</div>'}</div></section><section class="profile-section" id="profile-trophies-section" hidden><div class="profile-section-head"><h2>Galeria de títulos</h2></div><div class="trophy-grid" id="profile-trophies"></div></section>`}const labels={s2:'WB 2026 S2',s1:'WB 2026 S1',ewc:'EWC 2026',laff:'LAFF 2026 S1',sea:'FFWS SEA 2026 S1'};function statsPanel(c,key){const has=num(c.matches)>0,subtitle=key==='s2'?(has?'Temporada em andamento':'Temporada ainda não iniciada'):(c.team||'Desempenho registrado');return`<div class="player-season-head"><div><h3>${esc(c.name||labels[key]||'Competição')}</h3><p>${esc(subtitle)}</p></div></div><div class="stats-grid current-grid">${stat('Abates totais',fmt(c.kills),`Média: ${avg(c.kills,c.matches)} /queda`,c.rankKills)}${stat('Dano total',fmt(c.damage),c.damage?`Média: ${avg(c.damage,c.matches)} /queda`:'Sem registro',c.rankDamage)}${stat('Assistências',fmt(c.assists),c.assists?`Média: ${avg(c.assists,c.matches)} /queda`:'Sem registro',c.rankAssists)}${stat('Quedas jogadas',fmt(c.matches))}${stat('Recorde de abates',fmt(c.record||0),'Em uma única queda/dia')}${stat('MVPs recebidos',fmt(c.mvp||0))}</div>${stageRows(c.stages)}${!has?'<div class="season-empty">As estatísticas aparecerão aqui quando houver quedas registradas.</div>':''}`}function competitionTabs(keys){return`<section class="profile-section player-performance-section"><div class="profile-section-head"><h2>Desempenho por competição</h2><p>Selecione uma edição</p></div><nav class="player-season-tabs" aria-label="Competições do jogador">${keys.map((k,i)=>`<button type="button" data-player-season="${k}" class="${i===0?'is-active':''}" aria-selected="${i===0?'true':'false'}">${esc(labels[k]||k)}</button>`).join('')}</nav><div id="player-season-panel" class="player-season-panel"></div></section>`}function setTabs(active){document.querySelectorAll('[data-player-season]').forEach(b=>{const on=b.dataset.playerSeason===active;b.classList.toggle('is-active',on);b.setAttribute('aria-selected',on?'true':'false')})}async function ensureFullSeasonData(){if(state.seasonData)return state.seasonData;const slug=state.route.teamSlug;if(!slug)throw new Error('Dados da competição indisponíveis');state.seasonData=await getJSON(`player-data/seasons/${slug}.json?v=${VERSION}`);return state.seasonData}async function selectFullSeason(key){state.active=key;setTabs(key);const panel=document.getElementById('player-season-panel');if(!panel)return;if(key==='s2'){const c={name:labels.s2,...(state.player.s2||{}),...(state.current||{})};panel.innerHTML=statsPanel(c,key);return}panel.innerHTML='<div class="player-season-loading"><span></span><strong>Carregando competição...</strong></div>';try{const d=await ensureFullSeasonData(),c=d.players?.[state.player.id]?.[key];panel.innerHTML=c?statsPanel({...c,name:c.name||labels[key]},key):'<div class="season-empty">Nenhum dado registrado nesta competição.</div>'}catch{panel.innerHTML='<div class="season-empty">Não foi possível carregar esta competição.</div>'}}function fullRender(p,current){const keys=(p.availableSeasons||['s2']).filter((v,i,a)=>a.indexOf(v)===i);root.innerHTML=hero(p,'full')+competitionTabs(keys)+allTimeSection(p)+histories(p);document.querySelectorAll('[data-player-season]').forEach(b=>b.addEventListener('click',()=>selectFullSeason(b.dataset.playerSeason)));selectFullSeason(keys[0]||'s2')}function basicRender(p){const comps=p.competitions||[],keys=comps.map((c,i)=>c.key||`comp-${i}`);root.innerHTML=hero(p,'basic')+(comps.length?`<section class="profile-section player-performance-section"><div class="profile-section-head"><h2>Desempenho por competição</h2><p>Selecione uma edição</p></div><nav class="player-season-tabs">${comps.map((c,i)=>`<button type="button" data-basic-season="${i}" class="${i===0?'is-active':''}">${esc(c.name||'Competição')}</button>`).join('')}</nav><div id="player-season-panel" class="player-season-panel"></div></section>`:'')+allTimeSection(p,false)+histories(p);const render=i=>{document.querySelectorAll('[data-basic-season]').forEach((b,j)=>b.classList.toggle('is-active',j===i));const panel=document.getElementById('player-season-panel');if(panel)panel.innerHTML=statsPanel(comps[i]||{},keys[i])};document.querySelectorAll('[data-basic-season]').forEach((b,i)=>b.addEventListener('click',()=>render(i)));if(comps.length)render(0)}function historicalRender(p){root.innerHTML=hero(p,'historical')+allTimeSection(p)+histories(p)}function decodeRoute(id,code){if(!code)return null;if(code.startsWith('s:'))return{id,profileType:'full',teamSlug:code.slice(2),source:`player-data/s2/${code.slice(2)}.json`};if(code==='e')return{id,profileType:'basic',source:'player-data/basic/ewc-2026.json'};if(code==='l')return{id,profileType:'basic',source:'player-data/basic/laff-2026-s1.json'};if(code==='a')return{id,profileType:'basic',source:'player-data/basic/ffws-sea-2026.json'};if(code==='h')return{id,profileType:'historical',source:'player-data/historical.json'};return null}async function resolveRoute(){const routeMap=await getJSON(ROUTES),direct=params.get('id');if(direct&&routeMap.routes?.[direct])return decodeRoute(direct,routeMap.routes[direct]);const wanted=params.get('jogador')||params.get('player')||'',team=params.get('time')||params.get('team')||'';if(!wanted)return null;const idx=await getJSON(ALIASES),wk=norm(wanted),tk=norm(team),matches=(idx.players||[]).filter(p=>norm(p.name)===wk||(p.aliases||[]).some(a=>norm(a)===wk));let found=tk?matches.find(p=>norm(p.team)===tk||((tk==='loud'||tk==='loudsnickers')&&['loud','loudsnickers'].includes(norm(p.team)))):null;found=found||matches[0];return found&&routeMap.routes?.[found.id]?{...found,...decodeRoute(found.id,routeMap.routes[found.id])}:null}async function loadProfile(route){const tasks=[getJSON(`${route.source}?v=${VERSION}`),window.cffLoadTeamLogoMap?.().catch(()=>null)];if(route.profileType==='full')tasks.push(getJSON(CURRENT_STATS).catch(()=>({players:{}})));const [source,,stats]=await Promise.all(tasks),p=source.players?.[route.id];if(!p)throw new Error('Perfil não encontrado');return{p,current:stats?.players?.[route.id]||null}}function aliasesFor(p){return[p.name,...(p.aliases||[])].map(norm).filter(Boolean)}function tsvRows(text){return String(text||'').replace(/\r/g,'').split('\n').filter(Boolean).map(r=>r.split('\t'))}async function cachedText(key,url,ttl=1800000){try{const raw=localStorage.getItem(key);if(raw){const c=JSON.parse(raw);if(Date.now()-c.time<ttl)return c.text}}catch{}const r=await fetch(url,{cache:'default'});if(!r.ok)throw new Error('Fonte indisponível');const text=await r.text();try{localStorage.setItem(key,JSON.stringify({time:Date.now(),text}))}catch{}return text}function updateTitleCards(collective,individual){document.querySelectorAll('[data-title-collective] strong').forEach(e=>e.textContent=String(collective.length));document.querySelectorAll('[data-title-individual] strong').forEach(e=>e.textContent=String(individual.length));document.querySelectorAll('[data-title-collective] span').forEach(e=>e.textContent='Conquistas registradas');document.querySelectorAll('[data-title-individual] span').forEach(e=>e.textContent='Prêmios registrados');const box=document.getElementById('profile-trophies'),sec=document.getElementById('profile-trophies-section'),rows=[...collective.map(x=>({...x,kind:'Coletivo'})),...individual.map(x=>({...x,kind:'Individual'}))];if(box&&sec&&rows.length){sec.hidden=false;box.innerHTML=rows.map(x=>`<div class="trophy-card"><span>🏆</span><div><strong>${esc(x.event||'Título')}</strong><small>${esc(x.type||x.kind)}${x.team?` • ${esc(x.team)}`:''}</small></div></div>`).join('')}}async function loadTitles(p){const cfg=window.CFF_CONFIG?.sheets;if(!cfg)return;const aliases=aliasesFor(p);try{const[ct,it]=await Promise.all([cachedText('cff-player-titles-collective',cfg.recordesColetivos),cachedText('cff-player-titles-individual',cfg.recordesIndividuais)]),collective=tsvRows(ct).slice(1).map(r=>({event:r[0]?.trim(),type:r[1]?.trim(),team:r[2]?.trim(),players:(r[3]||'').split(',').map(s=>s.trim())})).filter(x=>x.event&&x.players.some(n=>aliases.includes(norm(n)))),individual=tsvRows(it).slice(1).map(r=>({event:r[0]?.trim(),type:r[1]?.trim(),team:r[2]?.trim(),player:r[3]?.trim()})).filter(x=>x.event&&aliases.includes(norm(x.player)));updateTitleCards(collective,individual)}catch{document.querySelectorAll('[data-title-collective] strong,[data-title-individual] strong').forEach(e=>e.textContent='—')}}async function boot(){try{const route=await resolveRoute();if(!route)throw new Error('Jogador não encontrado');state.route=route;const{p,current}=await loadProfile(route);state.player=p;state.current=current;document.title=`${p.name} | Central Free Fire`;if(route.profileType==='full')fullRender(p,current);else if(route.profileType==='basic')basicRender(p);else historicalRender(p);if(route.profileType!=='basic'){const secondary=()=>loadTitles(p);'requestIdleCallback'in window?requestIdleCallback(secondary,{timeout:2500}):setTimeout(secondary,500)}}catch(e){root.innerHTML=`<div class="player-error"><strong>${esc(e.message||'Não foi possível abrir o perfil.')}</strong><a class="player-back" href="index.html">Voltar para a página inicial</a></div>`}}boot();})();